#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static int *parse_array(const char *s, int *n) {
    size_t i = 0;
    while (s[i] && s[i] != '[') ++i;
    if (!s[i]) return NULL;
    ++i;
    while (s[i] && s[i] != '[') ++i;
    if (!s[i]) return NULL;
    ++i;
    int cap = 16, len = 0;
    int *a = (int *)malloc((size_t)cap * sizeof(int));
    if (!a) return NULL;
    while (s[i] && s[i] != ']') {
        while (s[i] && (isspace((unsigned char)s[i]) || s[i] == ',')) ++i;
        if (s[i] == ']') break;
        int sign = 1;
        if (s[i] == '-') { sign = -1; ++i; }
        int v = 0;
        while (isdigit((unsigned char)s[i])) {
            v = v * 10 + (s[i] - '0');
            ++i;
        }
        if (len == cap) {
            cap *= 2;
            int *tmp = (int *)realloc(a, (size_t)cap * sizeof(int));
            if (!tmp) { free(a); return NULL; }
            a = tmp;
        }
        a[len++] = sign * v;
        while (s[i] && (isspace((unsigned char)s[i]) || s[i] == ',')) ++i;
    }
    *n = len;
    return a;
}

int maxRotateFunction(int *nums, int numsSize) {
    long long total = 0, current = 0;
    for (int i = 0; i < numsSize; ++i) {
        total += nums[i];
        current += (long long)i * nums[i];
    }
    long long best = current;
    for (int k = 1; k < numsSize; ++k) {
        current += total - (long long)numsSize * nums[numsSize - k];
        if (current > best) best = current;
    }
    return (int)best;
}

