class Solution {
public:
    int maxRotateFunction(const vector<int>& nums) {
        const int n = (int)nums.size();
        long long total = 0, current = 0;
        for (int i = 0; i < n; ++i) {
            total += nums[i];
            current += 1LL * i * nums[i];
        }
        long long best = current;
        for (int k = 1; k < n; ++k) {
            current += total - 1LL * n * nums[n - k];
            best = max(best, current);
        }
        return (int)best;
    }
};

